using Foundgine.SupplyChain.Domain;
namespace Foundgine.SupplyChain.Application;
public sealed class SupplyChainApplication
{
 private readonly ICapabilityAuthorizer _auth; private readonly ISupplyChainQueries _queries; private readonly ISupplyChainMutations _mutations;
 public SupplyChainApplication(ICapabilityAuthorizer auth,ISupplyChainQueries queries,ISupplyChainMutations mutations){_auth=auth;_queries=queries;_mutations=mutations;}
 public object DescribeCapabilities(string actor)=>new{actor,capabilities=actor switch{"alice"=>new[]{"get_my_orders","get_order","get_product","get_shipment","place_order","cancel_order"},"bob"=>new[]{"get_my_orders","get_order","get_product","get_shipment","place_order","cancel_order","list_customers"},"carol"=>new[]{"get_product","get_inventory","update_inventory","create_shipment","update_shipment"},"dave"=>new[]{"get_product","get_inventory","list_products","list_suppliers","update_inventory"},"admin"=>new[]{"get_my_orders","get_order","get_product","get_shipment","place_order","cancel_order","list_customers","get_inventory","update_inventory","create_shipment","update_shipment","list_products","list_suppliers"},_=>Array.Empty<string>()}};
 public Task<object> GetMyOrders(string actor,int customerId,CancellationToken ct){_auth.Demand(actor,"get_my_orders",customerId);return _queries.GetOrders(customerId,ct);} public Task<object> GetOrder(string actor,int customerId,int orderId,CancellationToken ct){_auth.Demand(actor,"get_order",customerId);return _queries.GetOrder(customerId,orderId,ct);} public Task<object> GetShipment(string actor,int customerId,int shipmentId,CancellationToken ct){_auth.Demand(actor,"get_shipment",customerId);return _queries.GetShipment(customerId,shipmentId,ct);}
 public Task<object> ListProducts(string actor,CancellationToken ct){_auth.Demand(actor,"list_products");return _queries.ListProducts(ct);} public Task<object> ListCustomers(string actor,CancellationToken ct){_auth.Demand(actor,"list_customers");return _queries.ListCustomers(ct);} public Task<object> GetProduct(string actor,int id,CancellationToken ct){_auth.Demand(actor,"get_product");return _queries.GetProduct(id,ct);} public Task<object> GetInventory(string actor,int id,CancellationToken ct){_auth.Demand(actor,"get_inventory");return _queries.GetInventory(id,ct);} public Task<object> ListSuppliers(string actor,CancellationToken ct){_auth.Demand(actor,"list_suppliers");return _queries.ListSuppliers(ct);}
 public Task<object> UpdateInventory(string actor,int w,int p,int q,CancellationToken ct){_auth.Demand(actor,"update_inventory");return _mutations.UpdateInventory(w,p,q,ct);} public Task<object> CreateShipment(string actor,int o,int c,int w,string t,CancellationToken ct){_auth.Demand(actor,"create_shipment");return _mutations.CreateShipment(o,c,w,t,ct);} public Task<object> UpdateShipment(string actor,int id,string s,CancellationToken ct){_auth.Demand(actor,"update_shipment");return _mutations.UpdateShipment(id,s,ct);} public Task<object> PlaceOrder(string actor,int customerId,OrderLine[] lines,string key,CancellationToken ct){_auth.Demand(actor,"place_order",customerId);return _mutations.PlaceOrder(actor,customerId,lines,key,ct);} public Task<object> CancelOrder(string actor,int customerId,int orderId,CancellationToken ct){_auth.Demand(actor,"cancel_order",customerId);return _mutations.CancelOrder(actor,customerId,orderId,ct);}
}
